BEGIN READ ONLY; SELECT jsonb_build_object('readOnly',current_setting('transaction_read_only'),'schema',n.nspname,'table',c.relname,'relnatts',c.relnatts,'droppedSlots',(SELECT coalesce(jsonb_agg(a.attnum ORDER BY a.attnum),'[]'::jsonb) FROM pg_catalog.pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND a.attisdropped)) AS shape FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='turn_private' AND c.relname='work'; ROLLBACK;
